method rolling_max(numbers: seq<int>) returns (result: seq<int>)
    requires |numbers| > 0
    ensures |result| == |numbers|
    ensures forall i :: 0 <= i < |result| ==> result[i] == Max(numbers[0..i+1])
{
    var n := |numbers|;
    var maxVal := numbers[0];
    var res := new int[n];

    res[0] := numbers[0];

    var i := 1;
    while i < n
        invariant 1 <= i <= n
        invariant res[0..i] == [Max(numbers[0..j+1]) | j := 0..i-1]
    {
        maxVal := if numbers[i] > maxVal then numbers[i] else maxVal;
        res[i] := maxVal;
        i := i + 1;
    }

    result := res;
}
